package tw.rex.link;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.net.Uri;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
public final class UpdateClient {
 static final String BASE="https://raw.githubusercontent.com/rex0966445518/stock-monitor-updates/learning-island-updates/";
 static volatile boolean busy=false;
 public static void check(Activity a,boolean tv){if(busy)return;busy=true;ProgressDialog d=ProgressDialog.show(a,"一鍵更新","正在檢查最新版本……",true,false);new Thread(()->{try{JSONObject info=new JSONObject(new String(read(BASE+(tv?"tv.json":"parent.json"),65536),"UTF-8"));UpdateRules.validate(info,a.getPackageName());PackageInfo installed=a.getPackageManager().getPackageInfo(a.getPackageName(),PackageManager.GET_SIGNATURES);if(info.getLong("versionCode")<=installed.versionCode){a.runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(a).setTitle("已是最新版本").setMessage("目前版本："+installed.versionName).setPositiveButton("知道了",null).show();});return;}a.runOnUiThread(()->d.setMessage("正在下載新版，請稍候……"));byte[] data=read(info.getString("apkUrl"),52428800);if(data.length!=info.getLong("bytes"))throw new Exception("下載不完整，請重試");StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(data))hash.append(String.format(java.util.Locale.US,"%02x",b&255));if(!hash.toString().equalsIgnoreCase(info.getString("sha256")))throw new Exception("更新檔驗證失敗");File dir=new File(a.getCacheDir(),"updates");dir.mkdirs();File out=new File(dir,"package.apk");try(FileOutputStream f=new FileOutputStream(out)){f.write(data);}PackageInfo archive=a.getPackageManager().getPackageArchiveInfo(out.getAbsolutePath(),PackageManager.GET_SIGNATURES);if(archive==null||!a.getPackageName().equals(archive.packageName)||archive.versionCode!=info.getInt("versionCode")||archive.versionCode<=installed.versionCode)throw new Exception("更新套件或版本不符");Set<String> old=certificates(installed),fresh=certificates(archive);if(old.isEmpty()||!old.equals(fresh))throw new Exception("更新簽章不符，已拒絕安裝");a.runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(a).setTitle("找到新版 "+info.optString("versionName")).setMessage(info.optString("notes")+"\n\n會保留現有設定與配對；請依系統畫面確認安裝。").setPositiveButton("安裝更新",(dialog,w)->install(a)).setNegativeButton("稍後",null).show();});}catch(Exception e){a.runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(a).setTitle("更新未完成").setMessage("無法檢查或下載更新："+e.getMessage()+"\n請確認網路可連線至更新站，再重試。").setPositiveButton("知道了",null).show();});}finally{busy=false;}},"app-updater").start();}
 static Set<String> certificates(PackageInfo i){Set<String> s=new HashSet<String>();if(i.signatures!=null)for(android.content.pm.Signature signature:i.signatures)s.add(signature.toCharsString());return s;}
 static byte[] read(String address,int limit)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Cache-Control","no-cache");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("檔案過大");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
 static void install(Activity a){try{if(Build.VERSION.SDK_INT>=26&&!a.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(a).setTitle("允許安裝更新").setMessage("請在系統頁允許此 App 安裝未知應用程式；返回後按繼續安裝。").setPositiveButton("開啟權限設定",(d,w)->{a.startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));new AlertDialog.Builder(a).setMessage("授權完成後，按下繼續安裝。").setPositiveButton("繼續安裝",(d2,w2)->install(a)).setNegativeButton("稍後",null).show();}).setNegativeButton("取消",null).show();return;}Uri uri=Uri.parse("content://"+a.getPackageName()+".updates/package.apk");Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(intent);}catch(Exception e){new AlertDialog.Builder(a).setMessage("系統無法開啟安裝程式："+e.getMessage()).setPositiveButton("知道了",null).show();}}
}
